import type { ArchiveEntry, ArchiveFrame } from '@/types';

const CDN = 'https://4007607391.cdn.123clouddisk.com/4007607391';

const VIDEO_EXTS = ['.MOV', '.mov', '.MP4', '.mp4'];
function isVideo(filename: string): boolean {
  return VIDEO_EXTS.some((ext) => filename.endsWith(ext));
}

function makeFrame(url: string, filename: string, index: number): ArchiveFrame {
  return {
    url,
    label: `FRAME #${String(index + 1).padStart(2, '0')}`,
    caption: filename,
    isVideo: isVideo(filename),
  };
}

function firstImage(frames: ArchiveFrame[]): string {
  const img = frames.find((f) => !f.isVideo);
  return img ? img.url : frames[0]?.url ?? '';
}

