// Helper: parse "26.8.22-29" or "26.11.20-25" into a sortable number
function parseDate(dateStr: string): number {
  const m = dateStr.match(/(\d{2})\.(\d{1,2})\.(\d{1,2})/);
  if (!m) return 0;
  return parseInt(m[1]) * 10000 + parseInt(m[2]) * 100 + parseInt(m[3]);
}

// Build ArchiveEntry[] for 胶片留痕
export const filmTraceData: ArchiveEntry[] = filmTraceGroups
  .slice()
  .sort((a, b) => parseDate(b.date) - parseDate(a.date))
  .map((g, i) => {
    const frames = g.files.map((f, idx) => makeFrame(f.url, f.name, idx));
    return {
      id: `ft-${i}`,
      title: g.name,
      subtitle: '胶片留痕',
      date: g.date,
      year: `20${g.date.slice(0, 2)}`,
      description: `《${g.name}》胶片档案 · ${g.date}`,
      category: 'FILM TRACES',
      coverImage: firstImage(frames),
      frames,
    };
  });

// Build ArchiveEntry[] for 片场纪实
export const setDiaryData: ArchiveEntry[] = setDiaryGroups
  .slice()
  .sort((a, b) => parseDate(b.date) - parseDate(a.date))
  .map((g, i) => {
    const frames = g.files.map((f, idx) => makeFrame(f.url, f.name, idx));
    const nameWithoutDate = g.folder.replace(/（.*）$/, '');
    return {
      id: `sd-${i}`,
      title: nameWithoutDate,
      subtitle: '片场纪实',
      date: g.date,
      year: `20${g.date.slice(0, 2)}`,
      description: `《${nameWithoutDate}》片场纪实 · ${g.date}`,
      category: 'SET DIARY',
      coverImage: firstImage(frames),
      frames,
    };
  });

